// Factory pattern creates objects without exposing creation logic
@Component
public class PaymentProcessorFactory {

    public PaymentProcessor createProcessor(String type) {
        return switch (type.toLowerCase()) {
            case "credit" -> new CreditCardProcessor();
            case "debit" -> new DebitCardProcessor();
            case "upi" -> new UpiProcessor();
            default -> throw new IllegalArgumentException("Unknown payment type: " + type);
        }; // Switch expression (Java 17)
    }
}

@Service
public class CheckoutService {
    private final PaymentProcessorFactory factory;

    public void processPayment(Order order, String paymentType) {
        var processor = factory.createProcessor(paymentType); // Factory hides object creation
        processor.process(order.total());
    }
}

// CREATIONAL: Singleton (Spring does this for beans)
@Component
public class CartSessionManager {
    private static CartSessionManager instance; // Only one instance
}

// STRUCTURAL: Decorator (adds behavior)
public class DiscountedCart implements Cart {
    private final Cart baseCart;
    private final double discount;

    public double total() {
        return baseCart.total() * (1 - discount); // Wraps and modifies behavior
    }
}

// BEHAVIORAL: Strategy (swappable algorithm)
public interface PricingStrategy {
    double calculate(List<Item> items);
}

@Service
public class CartService {
    public double getTotal(List<Item> items, PricingStrategy strategy) {
        return strategy.calculate(items); // Algorithm injected at runtime
    }
}

@Service // Singleton pattern — one instance shared across app
public class CartService {
    private final CartRepository repository; // Injected by Factory (ApplicationContext)

    @Transactional // Proxy pattern — Spring wraps this method with transaction logic
    public void checkout(Long cartId) {
        var cart = repository.findById(cartId).orElseThrow();
        cart.markAsCheckedOut();
        repository.save(cart);
    }
}

@Component
public class OrderEventPublisher {
    private final ApplicationEventPublisher publisher; // Observer pattern

    public void notifyOrderPlaced(Order order) {
        publisher.publishEvent(new OrderPlacedEvent(order)); // All listeners notified
    }
}

// Template Method pattern in action
public List<Order> getRecentOrders() {
    return jdbcTemplate.query(
        "SELECT * FROM orders WHERE created_at > ?",
        (rs, rowNum) -> mapRowToOrder(rs) // You provide the mapping, Spring handles the rest
    );
}

// ANTI-PATTERN: God Class doing everything
@Service
public class CartManager { // Violates Single Responsibility Principle

    public void addItem(Long cartId, Item item) { /* cart logic */ }
    public void removeItem(Long cartId, Long itemId) { /* cart logic */ }
    public double calculateTotal(Long cartId) { /* pricing logic */ }
    public void applyDiscount(Long cartId, String code) { /* discount logic */ }
    public void processPayment(Long cartId, PaymentInfo payment) { /* payment logic */ }
    public void sendConfirmationEmail(Long cartId) { /* email logic */ }
    public void updateInventory(Long cartId) { /* inventory logic */ }
    public void generateInvoice(Long cartId) { /* invoice logic */ }
    // 2000 more lines...
}

// BETTER: Split into focused services
@Service public class CartService { /* cart operations */ }
@Service public class PricingService { /* pricing logic */ }
@Service public class PaymentService { /* payment processing */ }
@Service public class NotificationService { /* email/SMS */ }

// WITHOUT pattern knowledge: "We need to make the pricing logic flexible"
@Service
public class CartService {
    public double calculateTotal(List<Item> items, String customerType) {
        if (customerType.equals("premium")) {
            // calculate with premium discount
        } else if (customerType.equals("regular")) {
            // calculate regular price
        }
        // grows uncontrollably as new customer types are added
    }
}

// WITH pattern knowledge: "Let's apply the Strategy pattern"
public interface PricingStrategy {
    double calculate(List<Item> items);
}

@Service
public class CartService {
    public double calculateTotal(List<Item> items, PricingStrategy strategy) {
        return strategy.calculate(items); // Algorithm injected, extensible without modifying CartService
    }
}
